// src/components/RoleSelection.js
import React from "react";
import { useNavigate } from "react-router-dom";
import "../index.css";

const RoleSelection = () => {
  const navigate = useNavigate();

  // Helper function to store role before navigating
  const handleRoleSelect = (role, path) => {
    localStorage.setItem("intendedRole", role);
    navigate(path);
  };

  return (
    <div className="form-container">
      <h1 className="heading">SoftScale</h1>
      <div className="form-box">
        <h2>Select Your Role</h2>
        <p>Please choose how you want to use SoftScale.</p>

        <div className="role-buttons" style={{ marginTop: 20 }}>
          {/* Freelancer */}
          <button
            className="btn-primary"
            onClick={() => handleRoleSelect("freelancer", "/freelancer-form")}
            style={{ marginBottom: 12 }}
          >
            Continue as Freelancer
          </button>

          {/* Job Seeker */}
          <button
            className="btn-primary"
            onClick={() => handleRoleSelect("jobseeker", "/jobseeker-form")}
            style={{ marginBottom: 12 }}
          >
            Continue as Job Seeker
          </button>

          {/* Company Admin */}
          <button
            className="btn-primary"
            onClick={() => handleRoleSelect("company", "/company-form")}
            style={{ marginBottom: 0 }}
          >
            Continue as Company Admin
          </button>
        </div>
      </div>
    </div>
  );
};

export default RoleSelection;
